import pytest
from isort.parse import file_contents
from isort.settings import Config
from isort.exceptions import MissingSection


def test_file_contents_basic():
    content = "import os\nimport sys\n"
    parsed = file_contents(content)
    assert parsed.original_line_count == 3
    assert "os" in parsed.imports["STDLIB"]["straight"]
    assert "sys" in parsed.imports["STDLIB"]["straight"]


def test_file_contents_crlf_and_trailing():
    content = "import os\r\n"
    parsed = file_contents(content)
    assert parsed.line_separator == "\r\n"
    assert parsed.original_line_count == 2  # Appends empty line if ends with \n or \r


def test_file_contents_old_finders():
    config = Config(old_finders=True)
    content = "import os\n"
    parsed = file_contents(content, config=config)
    assert parsed.original_line_count == 2


def test_file_contents_section_comments():
    content = "import os\n"
    parsed = file_contents(content)
    assert parsed.import_index == 0


def test_file_contents_isort_imports_placement():
    content = "# isort:imports-CUSTOM\nimport os\n"
    parsed = file_contents(content)
    assert "CUSTOM" in parsed.place_imports


def test_file_contents_isort_imports_with_space_placement():
    content = "# isort: imports-CUSTOM\nimport os\n"
    parsed = file_contents(content)
    assert "CUSTOM" in parsed.place_imports


def test_file_contents_float_to_top():
    config = Config(float_to_top=True)
    content = "x = 1\n\nimport os\n"
    parsed = file_contents(content, config=config)
    assert parsed.import_index >= 0


def test_file_contents_float_to_top_skip():
    config = Config(float_to_top=True)
    content = "x = 1 # isort:skip\nimport os\n"
    parsed = file_contents(content, config=config)
    assert parsed.import_index >= 0


def test_file_contents_float_to_top_multiline_skip():
    config = Config(float_to_top=True)
    content = "x = (\n1\n) # isort:skip\nimport os\n"
    parsed = file_contents(content, config=config)
    assert parsed.import_index >= 0


def test_file_contents_semicolon_statements():
    content = "import os; import sys\n"
    parsed = file_contents(content)
    assert "os" in parsed.imports["STDLIB"]["straight"]
    assert "sys" in parsed.imports["STDLIB"]["straight"]


def test_file_contents_non_import_line():
    content = "print('hello')\n"
    parsed = file_contents(content)
    assert len(parsed.lines_without_imports) == 2


def test_file_contents_from_import_single_nested_comment():
    content = "from os import (\n    path,\n)\n"
    parsed = file_contents(content)
    assert "path" in parsed.imports["STDLIB"]["from"]["os"]


def test_file_contents_multiline_parentheses_import():
    content = "from os import (\n    path,\n    environ,\n)\n"
    parsed = file_contents(content)
    assert "path" in parsed.imports["STDLIB"]["from"]["os"]
    assert "environ" in parsed.imports["STDLIB"]["from"]["os"]


def test_file_contents_escaped_line_import():
    content = "import \\\n    os\n"
    parsed = file_contents(content)
    assert "os" in parsed.imports["STDLIB"]["straight"]


def test_file_contents_from_import_no_import_keyword():
    content = "from os\n"
    parsed = file_contents(content)
    assert len(parsed.lines_without_imports) == 2


def test_file_contents_cimport():
    content = "from os cimport path\n"
    parsed = file_contents(content)
    assert "path" in parsed.imports["STDLIB"]["from"]["os"]


def test_file_contents_straight_import_with_as_alias():
    config = Config(remove_redundant_aliases=True)
    content = "import os as os\n"
    parsed = file_contents(content, config=config)
    assert parsed.as_map["straight"] is not None


def test_file_contents_from_import_with_as_alias_and_combine():
    config = Config(combine_as_imports=True, verbose=True)
    content = "from os import path as p\n"
    parsed = file_contents(content, config=config)
    assert parsed.as_map["from"] is not None


def test_file_contents_from_import_verbose_only_modified():
    config = Config(verbose=True, only_modified=True)
    content = "from os import path\n"
    parsed = file_contents(content, config=config)
    assert "from-type place_module for os returned STDLIB" in parsed.verbose_output


def test_file_contents_from_import_verbose_print(capsys):
    config = Config(verbose=True, only_modified=False)
    content = "from os import path\n"
    file_contents(content, config=config)
    captured = capsys.readouterr()
    assert "place_module for os" in captured.out


def test_file_contents_missing_section():
    config = Config(sections=["FIRST"])
    content = "from unknown_mod import item\n"
    with pytest.raises(MissingSection):
        file_contents(content, config=config)


def test_file_contents_force_single_line_comments():
    config = Config(force_single_line=True)
    content = "from os import path\n"
    parsed = file_contents(content, config=config)
    assert "path" in parsed.imports["STDLIB"]["from"]["os"]


def test_file_contents_above_comments_cleaning():
    config = Config(treat_all_comments_as_code=False)
    content = "# above comment\nfrom os import path\n"
    parsed = file_contents(content, config=config)
    assert "os" in parsed.categorized_comments["above"]["from"]


def test_file_contents_root_update_existing():
    content = "from os import path\nfrom os import path\n"
    parsed = file_contents(content)
    assert "path" in parsed.imports["STDLIB"]["from"]["os"]


def test_file_contents_trailing_comma_in_from_import():
    content = "from os import path,\n"
    parsed = file_contents(content)
    assert "os" in parsed.trailing_commas


def test_file_contents_straight_import_in_loop():
    config = Config(verbose=True, only_modified=False)
    content = "import os\n"
    parsed = file_contents(content, config=config)
    assert "os" in parsed.imports["STDLIB"]["straight"]


def test_file_contents_empty_placed_module_warning():
    class DummyFinder:
        def __init__(self, *args, **kwargs):
            pass
        def __call__(self, mod, *args, **kwargs):
            return ""

    import isort.parse

    orig_finder = isort.parse.place.module
    isort.parse.place.module = DummyFinder()
    try:
        content = "import unknown_mod\n"
        parsed = file_contents(content)
        assert "" in parsed.imports
    finally:
        isort.parse.place.module = orig_finder
